use pizza_store;

-- Q1) What is the total revenue generated by pizza sales?

SELECT 
    SUM(p.price * od.quantity) AS total_revenue
FROM
    pizzas p
        JOIN
    order_details od ON p.pizza_id = od.pizza_id;


-- Q2) How many orders were placed?

SELECT 
    COUNT(DISTINCT (order_id)) AS Total_order
FROM
    orders;

-- Q3) Which pizza category generates the highest revenue?

SELECT 
    pt.category, SUM(od.quantity * p.price) AS highest_revenue
FROM
    order_details od
        JOIN
    pizzas p ON od.pizza_id = p.pizza_id
        JOIN
    pizza_types pt ON pt.pizza_type_id = p.pizza_type_id
GROUP BY pt.category
ORDER BY highest_revenue DESC
LIMIT 1;

-- Which are the top 5 best-selling pizzas by quantity?

SELECT 
    pt.pizza_name, SUM(od.quantity) AS total_quantity
FROM
    pizzas p
        JOIN
    order_details od ON p.pizza_id = od.pizza_id
        JOIN
    pizza_types pt ON pt.pizza_type_id = p.pizza_type_id
GROUP BY pt.pizza_name
ORDER BY total_quantity DESC
LIMIT 5;

-- Q5) Which month generates the highest revenue?

SELECT 
    MONTH(o.order_date) AS month_number,
    MONTHNAME(o.order_date) AS month_name,
    SUM(p.price * od.quantity) AS highest_revenue
FROM
    order_details od
        JOIN
    orders o ON od.order_id = o.order_id
        JOIN
    pizzas p ON p.pizza_id = od.pizza_id
GROUP BY MONTH(o.order_date) , MONTHNAME(o.order_date)
ORDER BY highest_revenue DESC
LIMIT 1;

-- Q6) What is the average order value?

SELECT 
    SUM(p.price * od.quantity) / COUNT(DISTINCT o.order_id) AS average_order_value
FROM
    order_details od
        JOIN
    pizzas p ON p.pizza_id = od.pizza_id
        JOIN
    orders o ON o.order_id = od.order_id;
    
    
-- Q7) What is the sales contribution of each pizza category?

with category_sales as(select pt.category, sum(p.price * od.quantity) as total_revenue
from pizza_types pt join pizzas p on p.pizza_type_id = pt. pizza_type_id
join order_details od on p.pizza_id = od.pizza_id
group by pt.category) 
select category, total_revenue, round(total_revenue * 100/ sum(total_revenue) over()) as contribution_percentage
from category_sales;

use pizza_store;
-- Q8) Display the total quantity of pizzas sold using a CTE.

with total_pizzas as 
(select sum(quantity) as total_qty
from order_details)
select * from total_pizzas;

-- 9) Calculate the total number of orders using a CTE.
with total_pizza_orders as
(select count(order_id) as total_orders
from orders)
select * from total_pizza_orders;

-- 10) Find the total revenue generated by each pizza using a CTE.

with pizza_revenue as 
(select pizza_name, sum(p.price * od.quantity) as total_revenue
from pizzas p join pizza_types pt on p.pizza_type_id = pt.pizza_type_id
join order_details od on p.pizza_id = od.pizza_id 
group by pizza_name)
select * from pizza_revenue;

-- 11) Calculate the total quantity sold for each pizza type.

with pizza_quantity as
(select pt.pizza_name, count(od.quantity) 
as total_qty
from pizzas p 
join order_details od 
  on p.pizza_id = od.pizza_id
join pizza_types pt 
  on pt.pizza_type_id = p.pizza_type_id
group by pt.pizza_name)
select * from pizza_quantity
order by total_qty desc;

-- Find the average price of pizzas using a CTE.

with price_average as 
(select avg(p.price * od.quantity) 
as average_price 
from pizzas p 
join order_details od
on p.pizza_id = od.pizza_id)
select * from price_average;

-- 13) Count how many different pizza types are available in each category.
WITH type_of_pizza as 
(SELECT category, COUNT(pizza_type_id) as total_pizza_type
FROM pizza_types
GROUP BY category)
SELECT * FROM type_of_pizza
ORDER BY total_pizza_type desc;

-- 14) Find the total revenue generated by each pizza category.
WITH pizza_revenue as 
(SELECT pt.category, sum(p.price * od.quantity) 
as total_revenue
FROM pizzas p 
JOIN pizza_types pt 
ON p.pizza_type_id = pt.pizza_type_id
JOIN order_details od 
ON  p.pizza_id = od.pizza_id
GROUP BY category)
SELECT * FROM pizza_revenue
ORDER BY total_revenue desc;